// agent_loop condition: returns true to take another step.
// Stop when the agent finishes, or after 10 steps so a confused planner can't run forever.
function shouldTakeAnotherStep() {
  const lastStep = $.record_step_ref || {};
  const result = lastStep.result || {};
  if (result.done) {
    return false;
  }
  return $.agent_loop_ref.iteration < $.maxSteps;
}

shouldTakeAnotherStep();

