// check_step: checks the planner's choice before anything runs. The tool must be on the
// allowlist, the arguments must name one package version, and the same call must not already be
// in the ledger; otherwise the step is skipped.
//
// Inputs:  $.plan          the planner's answer: action, tool, arguments, reason
//          $.allowedTools  the tool names that prepare_agent_context kept
//          $.ledgerText    the ledger so far, as JSON text (null at first)
//          $.dependenciesText  the current dependencies, as JSON text, e.g. {"express": "4.17.1"}
// Output:  decision ("call", "skip" or "finish"), plus tool, arguments, reason and problem
//
// Text is joined with + because Conductor treats a dollar sign followed by a brace in a task
// input as a workflow reference.

function isAllowed(tool) {
  for (let i = 0; i < $.allowedTools.length; i++) {
    if (String($.allowedTools[i]) === tool) {
      return true;
    }
  }
  return false;
}

// The ledger entry for an earlier call with the same tool, package and version, or null.
function findEarlierCall(tool, packageName, packageVersion) {
  if (!$.ledgerText) {
    return null;
  }
  let ledger = [];
  try {
    ledger = JSON.parse($.ledgerText);
  } catch (e) {
    return null;
  }
  for (const entry of ledger) {
    if (entry.tool === tool && entry.packageName === packageName && entry.packageVersion === packageVersion) {
      return entry;
    }
  }
  return null;
}

// The current dependencies that have no POST_scan call in the ledger yet, e.g. ["lodash@4.17.20"].
function unscannedDependencies() {
  let dependencies = {};
  try {
    dependencies = JSON.parse($.dependenciesText || "{}");
  } catch (e) {
    return [];
  }
  let ledger = [];
  if ($.ledgerText) {
    try {
      ledger = JSON.parse($.ledgerText);
    } catch (e) {
      ledger = [];
    }
  }
  const missing = [];
  for (const name of Object.keys(dependencies)) {
    const version = String(dependencies[name]);
    let scanned = false;
    for (const entry of ledger) {
      if (entry.tool === "POST_scan" && entry.packageName === name && entry.packageVersion === version) {
        scanned = true;
      }
    }
    if (!scanned) {
      missing.push(name + "@" + version);
    }
  }
  return missing;
}

function checkStep() {
  // If the model returned text instead of JSON, try to parse it.
  let plan = $.plan || {};
  if (typeof plan === "string") {
    try {
      plan = JSON.parse(plan);
    } catch (e) {
      plan = {};
    }
  }

  const action = String(plan.action || "").trim();
  if (action === "finish") {
    // e.g. "can't finish yet: scan these current dependencies first: lodash@4.17.20, express@4.17.1"
    const missing = unscannedDependencies();
    if (missing.length > 0) {
      return { decision: "skip", problem: "can't finish yet: scan these current dependencies first: " + missing.join(", ") };
    }
    return { decision: "finish", reason: String(plan.reason || "") };
  }
  if (action !== "call_tool") {
    return { decision: "finish", problem: "the planner returned no valid action, so the agent stopped" };
  }

  // e.g. "POST_scan"
  const tool = String(plan.tool || "").trim();
  if (!isAllowed(tool)) {
    return { decision: "skip", problem: "'" + tool + "' is not an allowed tool" };
  }

  const args = plan.arguments || {};
  const packageName = String(args.packageName || "").trim();
  const packageVersion = String(args.packageVersion || "").trim();
  if (packageName === "" || packageVersion === "") {
    return { decision: "skip", problem: "a tool call needs both packageName and packageVersion" };
  }

  // e.g. "POST_scan was already called for express@4.20.0 in step 6; use that result"
  const earlier = findEarlierCall(tool, packageName, packageVersion);
  if (earlier) {
    return {
      decision: "skip",
      problem: tool + " was already called for " + packageName + "@" + packageVersion +
        " in step " + earlier.step + "; use that result"
    };
  }

  return {
    decision: "call",
    tool: tool,
    arguments: { packageName: packageName, packageVersion: packageVersion },
    reason: String(plan.reason || "")
  };
}

checkStep();

// record_step: adds this step to the ledger, the running list of everything the agent did.
// The planner reads the ledger at the start of the next step, and the final plan is written from it.
//
// Inputs:  $.check               the output of check_step
//          $.toolOutput          the output of call_npm_tool (only used when check_step said "call")
//          $.previousLedgerText  the ledger so far, from the workflow variable ledgerText (null at first)
// Output:  ledgerText, steps, done (true when the agent decided to finish)

// The first piece of text in an MCP tool result.
function firstText(output) {
  const content = output.content;
  if (!content || content.length === 0) {
    return "";
  }
  return String(content[0].text || "");
}

// Keeps only the fields an upgrade plan needs. The full tool output also holds the brief and
// every dependency's licenses, which would fill the planner's prompt.
function summarizeToolOutput(output) {
  if (!output) {
    return { error: "the tool call failed or returned nothing" };
  }
  const text = firstText(output);
  if (output.isError === true) {
    return { error: text.substring(0, 500) || "the tool reported an error" };
  }
  if (text === "") {
    // No content at all: the call most likely failed or timed out before the workflow finished.
    // An optional task that fails still gives an output, just without content.
    let detail = "";
    if (output.error) {
      detail = ": " + String(output.error).substring(0, 300);
    }
    return { error: "the tool returned no result; the call may have timed out before the workflow finished" + detail };
  }

  let data = null;
  try {
    data = JSON.parse(text);
  } catch (e) {
    return { text: text.substring(0, 1500) };
  }

  const keep = ["warning", "aiVerdict", "route", "routeReasons", "rejectReasons", "recommendedVersion", "upgradeStatus",
    "highOrCriticalAdvisories", "dependencyAdvisories", "licensePolicyViolations", "missingSources",
    "advisories", "upgrade"];
  const summary = {};
  for (const key of keep) {
    if (data[key] !== undefined) {
      summary[key] = data[key];
    }
  }

  // A scan of a version deps.dev doesn't know looks clean: OSV returns no advisories and the
  // dependency lookup is optional. Flag it, even if the route's script didn't.
  if (!summary.warning && data.sources && data.sources.dependencyGraph === false) {
    summary.warning = "deps.dev has no data for this version; it may not exist, so this result proves nothing";
  }

  // scan_npm_package returns its dependency facts in one object. Keep the counts, and one line per
  // vulnerable dependency, e.g. {"package": "qs@6.7.0", "severity": "1 HIGH, 2 MODERATE", "fixedIn": "6.16.0"}
  const deps = data.transitiveDependencies;
  if (deps) {
    const vulnerable = [];
    for (const dep of deps.packagesWithAdvisories || []) {
      vulnerable.push({ package: dep.package, severity: dep.severity, fixedIn: dep.fixedIn || null });
    }
    summary.dependencies = {
      total: deps.total,
      checked: deps.checked,
      advisories: deps.uniqueAdvisoryCount,
      highOrCritical: deps.highOrCriticalAdvisories,
      unfixedHighOrCritical: deps.unfixedHighOrCritical,
      vulnerable: vulnerable
    };
  }
  return summary;
}

function recordStep() {
  let ledger = [];
  if ($.previousLedgerText) {
    try {
      ledger = JSON.parse($.previousLedgerText);
    } catch (e) {
      ledger = [];
    }
  }

  const check = $.check || {};
  const entry = { step: ledger.length + 1 };
  let done = false;

  if (check.decision === "call") {
    // e.g. {"step": 2, "tool": "POST_scan", "packageName": "express", "packageVersion": "4.17.1", ...}
    entry.tool = String(check.tool);
    entry.packageName = String(check.arguments.packageName);
    entry.packageVersion = String(check.arguments.packageVersion);
    entry.reason = String(check.reason || "");
    entry.result = summarizeToolOutput($.toolOutput);
  } else if (check.decision === "skip") {
    entry.skipped = String(check.problem);
  } else {
    entry.finished = String(check.reason || check.problem || "the agent finished");
    done = true;
  }

  ledger.push(entry);
  return { ledgerText: JSON.stringify(ledger), steps: ledger.length, done: done };
}

recordStep();

